-- Create the audit trail table for urgency status changes
CREATE TABLE urgency_status_log (
    log_number SERIAL PRIMARY KEY,
    patient_id TEXT NOT NULL,
    change_date DATE NOT NULL DEFAULT CURRENT_DATE,
    status_from TEXT,
    status_to TEXT
);

-- Create the trigger function to log urgency changes
CREATE OR REPLACE FUNCTION log_urgency_change()
RETURNS TRIGGER AS $$
BEGIN
    -- Only log if med_urgency actually changed
    IF OLD.med_urgency IS DISTINCT FROM NEW.med_urgency THEN
        INSERT INTO urgency_status_log (patient_id, change_date, status_from, status_to)
        VALUES (NEW.clin_recip_registry, CURRENT_DATE, OLD.med_urgency, NEW.med_urgency);
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Create the trigger on the clinical table
CREATE TRIGGER trg_urgency_change
AFTER UPDATE ON clinical
FOR EACH ROW
WHEN (OLD.med_urgency IS DISTINCT FROM NEW.med_urgency)
EXECUTE FUNCTION log_urgency_change();

